// IdentityServiceHandler is an implementation of the rill.v1.IdentityService service.
type IdentityServiceHandler interface {
	// The caller: principal, teams, capabilities and token.
	GetCaller(context.Context, *connect.Request[v1.GetCallerRequest]) (*connect.Response[v1.GetCallerResponse], error)
	// Mint a capability token attenuated from the caller's.
	IssueToken(context.Context, *connect.Request[v1.IssueTokenRequest]) (*connect.Response[v1.IssueTokenResponse], error)
	// Revoke a token (and every token attenuated from it). Callers may
	// revoke a token they present; administrators any token id.
	RevokeToken(context.Context, *connect.Request[v1.RevokeTokenRequest]) (*connect.Response[v1.RevokeTokenResponse], error)
	// End a session; every token issued under it is refused from then on.
	RevokeSession(context.Context, *connect.Request[v1.RevokeSessionRequest]) (*connect.Response[v1.RevokeSessionResponse], error)
	// Store a new signing key now; it activates after the activation delay.
	RotateTokenKeys(context.Context, *connect.Request[v1.RotateTokenKeysRequest]) (*connect.Response[v1.RotateTokenKeysResponse], error)
	// The token signing keys, active and retired.
	ListTokenKeys(context.Context, *connect.Request[v1.ListTokenKeysRequest]) (*connect.Response[v1.ListTokenKeysResponse], error)
	// One OpenID Connect or SAML provider; org administrators.
	GetIdentityProvider(context.Context, *connect.Request[v1.GetIdentityProviderRequest]) (*connect.Response[v1.GetIdentityProviderResponse], error)
	// An organization's identity providers; org administrators.
	ListIdentityProviders(context.Context, *connect.Request[v1.ListIdentityProvidersRequest]) (*connect.Response[v1.ListIdentityProvidersResponse], error)
	// Replace a provider, or with `allow_missing` create it; org
	// administrators.
	UpdateIdentityProvider(context.Context, *connect.Request[v1.UpdateIdentityProviderRequest]) (*connect.Response[v1.UpdateIdentityProviderResponse], error)
	// Remove a provider; org administrators.
	DeleteIdentityProvider(context.Context, *connect.Request[v1.DeleteIdentityProviderRequest]) (*connect.Response[v1.DeleteIdentityProviderResponse], error)
	// An organization's users; org administrators.
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	// Suspend or reactivate a user, or set their roles. Suspension refuses
	// every token the user holds at once.
	UpdateUser(context.Context, *connect.Request[v1.UpdateUserRequest]) (*connect.Response[v1.UpdateUserResponse], error)
	// Register an agent: org administrators, or a user for agents they
	// sponsor.
	CreateAgent(context.Context, *connect.Request[v1.CreateAgentRequest]) (*connect.Response[v1.CreateAgentResponse], error)
	// One agent.
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.GetAgentResponse], error)
	// An organization's agents.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// Suspend or reactivate an agent, or replace its registration.
	UpdateAgent(context.Context, *connect.Request[v1.UpdateAgentRequest]) (*connect.Response[v1.UpdateAgentResponse], error)
	// Issuers whose workload JWTs may be exchanged for agent tokens; org
	// administrators.
	ListWorkloadIssuers(context.Context, *connect.Request[v1.ListWorkloadIssuersRequest]) (*connect.Response[v1.ListWorkloadIssuersResponse], error)
	// Replace an issuer, or with `allow_missing` create it.
	UpdateWorkloadIssuer(context.Context, *connect.Request[v1.UpdateWorkloadIssuerRequest]) (*connect.Response[v1.UpdateWorkloadIssuerResponse], error)
	// Remove an issuer.
	DeleteWorkloadIssuer(context.Context, *connect.Request[v1.DeleteWorkloadIssuerRequest]) (*connect.Response[v1.DeleteWorkloadIssuerResponse], error)
	// Stop an agent, a session, everything a sponsor's agents do, or every
	// agent running as a model; org administrators. Tokens are refused at
	// once, and the lander ejects their queued work.
	KillSwitch(context.Context, *connect.Request[v1.KillSwitchRequest]) (*connect.Response[v1.KillSwitchResponse], error)
	// Bearer credentials a provisioning system calls the org's SCIM endpoint
	// (`/scim/v2/<org>`) with; org administrators. The secret is returned
	// once.
	CreateScimCredential(context.Context, *connect.Request[v1.CreateScimCredentialRequest]) (*connect.Response[v1.CreateScimCredentialResponse], error)
	// An organization's SCIM credentials, revoked ones included.
	ListScimCredentials(context.Context, *connect.Request[v1.ListScimCredentialsRequest]) (*connect.Response[v1.ListScimCredentialsResponse], error)
	// Revoke a SCIM credential; it stays listed as revoked.
	DeleteScimCredential(context.Context, *connect.Request[v1.DeleteScimCredentialRequest]) (*connect.Response[v1.DeleteScimCredentialResponse], error)
}

